import { cva, type VariantProps } from 'class-variance-authority';
import { type MotionProps, motion } from 'motion/react';
import React from 'react';

import { Heading, Text } from '@/components/ui/typography';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const cardVariants = cva(
  'flex min-w-0 flex-col rounded-lg border border-solid border-border bg-card text-card-foreground',
  {
    defaultVariants: {
      size: 'md',
      variant: 'elevated',
    },
    variants: {
      size: {
        default: 'max-w-md gap-4 px-8 py-6',
        full: 'w-full gap-4 px-8 py-6',
        lg: 'max-w-lg gap-4 px-10 py-8',
        md: 'max-w-md gap-4 px-8 py-6',
        sm: 'max-w-sm gap-2 px-6 py-4',
        xl: 'max-w-xl gap-6 px-12 py-10',
      },
      variant: {
        choice:
          'rounded-md border-2 border-solid p-4 shadow-none transition-all group-data-[state=checked]:!border-selected hover:shadow-lg',
        elevated: 'shadow-lg',
        ghost: 'border-0 bg-transparent shadow-none dark:bg-transparent',
        outlined: 'border-1',
        standard: '',
      },
    },
  }
);

export type CardVariant = VariantProps<typeof cardVariants>['variant'];
export type CardSize = VariantProps<typeof cardVariants>['size'];

type BaseCardProps = SharedProps & {
  size?: CardSize;
  variant?: CardVariant;
  className?: string | undefined;
};

type StaticCardProps = BaseCardProps & Omit<React.ComponentProps<'div'>, keyof BaseCardProps> & { animated?: false };
type AnimatedCardProps = BaseCardProps & Omit<MotionProps, keyof BaseCardProps> & { animated: true };

export type CardProps = StaticCardProps | AnimatedCardProps;

const Card = React.forwardRef<HTMLDivElement, CardProps>(({ className, size, variant, testId, ...props }, ref) => {
  const cardClassName = cn(cardVariants({ size, variant }), className);

  if (props.animated === true) {
    const { animated: _animated, ...motionProps } = props;
    return <motion.div className={cardClassName} data-slot="card" data-testid={testId} ref={ref} {...motionProps} />;
  }

  const { animated: _animated, ...staticProps } = props;
  return <div className={cardClassName} data-slot="card" data-testid={testId} ref={ref} {...staticProps} />;
});

Card.displayName = 'Card';

const cardHeaderVariants = cva(
  '@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-6',
  {
    defaultVariants: {
      padding: 'none',
      spacing: 'normal',
    },
    variants: {
      padding: {
        lg: 'px-8',
        md: 'px-6',
        none: '',
        sm: 'px-3',
      },
      spacing: {
        loose: 'gap-2',
        normal: 'gap-1.5',
        tight: 'gap-1',
      },
    },
  }
);

interface CardHeaderProps extends React.ComponentProps<'div'>, VariantProps<typeof cardHeaderVariants>, SharedProps {}

const CardHeader = React.forwardRef<HTMLDivElement, CardHeaderProps>(
  ({ className, spacing, padding, testId, ...props }, ref) => (
    <div
      className={cn(cardHeaderVariants({ padding, spacing }), className)}
      data-slot="card-header"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

CardHeader.displayName = 'CardHeader';

const CardTitle = React.forwardRef<
  HTMLHeadingElement,
  React.ComponentProps<'div'> & SharedProps & { level?: 1 | 2 | 3 | 4; spacing?: 'loose' }
>(({ className, level = 4, spacing, testId, children, ...props }, ref) => {
  let content: React.ReactNode = null;
  if (children) {
    content = typeof children === 'string' ? <Heading level={level}>{children}</Heading> : children;
  }

  return (
    <div
      className={cn(spacing === 'loose' && 'gap-3', className)}
      data-slot="card-title"
      data-testid={testId}
      ref={ref}
      {...props}
    >
      {content}
    </div>
  );
});

CardTitle.displayName = 'CardTitle';

const CardDescription = React.forwardRef<HTMLDivElement, React.ComponentProps<'div'> & SharedProps>(
  ({ className, testId, children, ...props }, ref) => {
    let content: React.ReactNode = null;
    if (children) {
      content = typeof children === 'string' ? <Text>{children}</Text> : children;
    }

    return (
      <div
        className={cn('text-sm text-muted-foreground', className)}
        data-slot="card-description"
        data-testid={testId}
        ref={ref}
        {...props}
      >
        {content}
      </div>
    );
  }
);

CardDescription.displayName = 'CardDescription';

const CardAction = React.forwardRef<HTMLDivElement, React.ComponentProps<'div'> & SharedProps>(
  ({ className, testId, ...props }, ref) => (
    <div
      className={cn('col-start-2 row-span-2 row-start-1 self-start justify-self-end', className)}
      data-slot="card-action"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

CardAction.displayName = 'CardAction';

const cardContentVariants = cva('', {
  defaultVariants: {
    padding: 'none',
    space: 'md',
  },
  variants: {
    variant: {
      'selection-indicator':
        'flex aspect-square size-4 shrink-0 items-center justify-center rounded-full border !border-input p-0 text-selected shadow-xs transition outline-none group-data-[state=checked]:!border-selected focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:bg-input/30 dark:aria-invalid:ring-destructive/40',
    },
    padding: {
      lg: 'px-8',
      md: 'px-6',
      none: '',
      sm: 'px-3',
    },
    space: {
      lg: 'space-y-6',
      md: 'space-y-4',
      none: '',
      sm: 'space-y-2',
    },
  },
});

interface CardContentProps extends React.ComponentProps<'div'>, VariantProps<typeof cardContentVariants>, SharedProps {}

const CardContent = React.forwardRef<HTMLDivElement, CardContentProps>(
  ({ className, padding, space, variant, testId, ...props }, ref) => (
    <div
      className={cn(cardContentVariants({ padding, space, variant }), className)}
      data-slot="card-content"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

CardContent.displayName = 'CardContent';

const cardFooterVariants = cva('flex items-center [.border-t]:pt-6', {
  defaultVariants: {
    direction: 'row',
    gap: 'sm',
    justify: 'between',
    padding: 'none',
  },
  variants: {
    direction: {
      column: 'flex-col',
      row: 'flex-row',
    },
    gap: {
      lg: 'gap-6',
      md: 'gap-4',
      none: '',
      sm: 'gap-2',
    },
    justify: {
      around: 'justify-around',
      between: 'justify-between',
      center: 'justify-center',
      end: 'justify-end',
      start: 'justify-start',
    },
    padding: {
      lg: 'px-8',
      md: 'px-6',
      none: '',
      sm: 'px-3',
    },
  },
});

interface CardFooterProps extends React.ComponentProps<'div'>, VariantProps<typeof cardFooterVariants>, SharedProps {}

const CardFooter = React.forwardRef<HTMLDivElement, CardFooterProps>(
  ({ className, direction, justify, gap, padding, testId, ...props }, ref) => (
    <div
      className={cn(cardFooterVariants({ direction, gap, justify, padding }), className)}
      data-slot="card-footer"
      data-testid={testId}
      ref={ref}
      {...props}
    />
  )
);

CardFooter.displayName = 'CardFooter';

const cardFormVariants = cva('grid w-full items-center', {
  defaultVariants: {
    gap: 'md',
  },
  variants: {
    gap: {
      lg: 'gap-6',
      md: 'gap-4',
      sm: 'gap-2',
    },
  },
});

interface CardFormProps extends React.ComponentProps<'div'>, VariantProps<typeof cardFormVariants>, SharedProps {}

const CardForm = React.forwardRef<HTMLDivElement, CardFormProps>(({ className, gap, testId, ...props }, ref) => (
  <div className={cn(cardFormVariants({ gap }), className)} data-testid={testId} ref={ref} {...props} />
));

CardForm.displayName = 'CardForm';

const cardFieldVariants = cva('flex flex-col', {
  defaultVariants: {
    spacing: 'normal',
  },
  variants: {
    spacing: {
      loose: 'space-y-2',
      normal: 'space-y-1.5',
      tight: 'space-y-1',
    },
  },
});

interface CardFieldProps extends React.ComponentProps<'div'>, VariantProps<typeof cardFieldVariants>, SharedProps {}

const CardField = React.forwardRef<HTMLDivElement, CardFieldProps>(({ className, spacing, testId, ...props }, ref) => (
  <div className={cn(cardFieldVariants({ spacing }), className)} data-testid={testId} ref={ref} {...props} />
));

CardField.displayName = 'CardField';

export { Card, CardAction, CardContent, CardDescription, CardField, CardFooter, CardForm, CardHeader, CardTitle };

import { Radio as RadioGroupPrimitive } from '@base-ui/react/radio';
import { Circle } from 'lucide-react';
import { AnimatePresence, motion, type Transition } from 'motion/react';
import { type ComponentProps, forwardRef, type HTMLAttributes } from 'react';

import { Card, CardContent, CardDescription, CardHeader, type CardProps, CardTitle } from '@/components/ui/card';
import { RadioGroup } from '@/components/ui/radio-group';
import { renderWithDataState } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const DEFAULT_TRANSITION = { damping: 16, stiffness: 200, type: 'spring' } satisfies Transition;

export type ChoiceboxProps = ComponentProps<typeof RadioGroup> & SharedProps;

export const Choicebox = ({ className, testId, ...props }: ChoiceboxProps) => (
  <RadioGroup className={cn('w-full', className)} data-testid={testId} {...props} />
);

export type ChoiceboxItemProps = ComponentProps<typeof RadioGroupPrimitive.Root> &
  SharedProps &
  Partial<Pick<CardProps, 'size'>>;

export const ChoiceboxItem = forwardRef<HTMLButtonElement, ChoiceboxItemProps>(
  ({ className, children, testId, size, ...props }, ref) => (
    <RadioGroupPrimitive.Root
      {...props}
      className="group"
      nativeButton
      ref={ref}
      render={renderWithDataState('button')}
    >
      <Card
        className={cn('flex cursor-pointer flex-row items-start justify-between text-left', className)}
        data-testid={testId}
        size={size}
        variant="choice"
      >
        {children}
      </Card>
    </RadioGroupPrimitive.Root>
  )
);

ChoiceboxItem.displayName = 'ChoiceboxItem';

export type ChoiceboxItemHeaderProps = ComponentProps<typeof CardHeader>;

export const ChoiceboxItemHeader = ({ className, ...props }: ComponentProps<typeof CardHeader>) => (
  <CardHeader className={cn('flex-1', className)} {...props} />
);

export type ChoiceboxItemTitleProps = ComponentProps<typeof CardTitle>;

export const ChoiceboxItemTitle = ({ className, ...props }: ChoiceboxItemTitleProps) => (
  <CardTitle className={cn('flex items-center', className)} spacing="loose" {...props} />
);

export type ChoiceboxItemSubtitleProps = HTMLAttributes<HTMLSpanElement>;

export const ChoiceboxItemSubtitle = ({ className, ...props }: ChoiceboxItemSubtitleProps) => (
  <span className={cn('text-xs font-normal text-muted-foreground', className)} {...props} />
);

export type ChoiceboxItemDescriptionProps = ComponentProps<typeof CardDescription>;

export const ChoiceboxItemDescription = ({ className, ...props }: ChoiceboxItemDescriptionProps) => (
  <CardDescription className={className} {...props} />
);

export type ChoiceboxItemContentProps = ComponentProps<typeof CardContent>;

export const ChoiceboxItemContent = ({ className, ...props }: ChoiceboxItemContentProps) => (
  <CardContent className={className} variant="selection-indicator" {...props} />
);

export type ChoiceboxItemIndicatorProps = ComponentProps<typeof RadioGroupPrimitive.Indicator> & {
  transition?: Transition;
};

export const ChoiceboxItemIndicator = ({
  className,
  transition = DEFAULT_TRANSITION,
  ...props
}: ChoiceboxItemIndicatorProps) => (
  <RadioGroupPrimitive.Indicator
    className={cn('flex items-center justify-center data-[unchecked]:hidden', className)}
    data-slot="radio-group-indicator"
    {...props}
  >
    <AnimatePresence>
      <motion.div
        animate={{ opacity: 1, scale: 1 }}
        data-slot="radio-group-indicator-circle"
        exit={{ opacity: 0, scale: 0.95 }}
        initial={{ opacity: 0, scale: 0.95 }}
        key="radio-group-indicator-circle"
        transition={transition}
      >
        <Circle className="size-2.5 fill-current text-current" />
      </motion.div>
    </AnimatePresence>
  </RadioGroupPrimitive.Indicator>
);

import { Radio as RadioPrimitive } from '@base-ui/react/radio';
import { RadioGroup as RadioGroupPrimitive } from '@base-ui/react/radio-group';
import { Circle } from 'lucide-react';
import { AnimatePresence, type HTMLMotionProps, motion, type Transition } from 'motion/react';
import type React from 'react';

import { splitMotionProps } from '@/registry/base-nova/protoform/lib/base-ui-compat';
import { cn, type SharedProps } from '@/registry/base-nova/protoform/lib/utils';

const DEFAULT_TRANSITION = { duration: 0.15 } satisfies Transition;

type RadioGroupOrientation = 'vertical' | 'horizontal';

type RadioGroupProps = React.ComponentProps<typeof RadioGroupPrimitive> &
  SharedProps & {
    orientation?: RadioGroupOrientation;

    transition?: Transition;
  };

function RadioGroup(allProps: RadioGroupProps) {
  const { className, orientation = 'vertical', testId, onValueChange, ...props } = allProps;

  const hasValueProp = 'value' in allProps;
  const valueOverride = hasValueProp && allProps.value === undefined ? { value: '' } : undefined;

  return (
    <RadioGroupPrimitive
      aria-orientation={orientation}
      className={(state) =>
        cn(
          'grid w-full gap-2',
          orientation === 'horizontal' && 'grid-cols-2',
          typeof className === 'function' ? className(state) : className
        )
      }
      data-orientation={orientation}
      data-slot="radio-group"
      data-testid={testId}
      onValueChange={onValueChange}
      {...props}
      {...valueOverride}
    />
  );
}

type RadioGroupIndicatorProps = React.ComponentProps<typeof RadioPrimitive.Indicator> & {
  transition: Transition;
};

function RadioGroupIndicator({ className, transition, ...props }: RadioGroupIndicatorProps) {
  return (
    <RadioPrimitive.Indicator
      className={(state) =>
        cn(
          'flex items-center justify-center data-[unchecked]:hidden',
          typeof className === 'function' ? className(state) : className
        )
      }
      data-slot="radio-group-indicator"
      keepMounted
      {...props}
    >
      <AnimatePresence>
        <motion.div
          animate={{ opacity: 1, scale: 1 }}
          className="flex items-center justify-center"
          data-slot="radio-group-indicator-circle"
          exit={{ opacity: 0, scale: 0.95 }}
          initial={{ opacity: 0, scale: 0.95 }}
          key="radio-group-indicator-circle"
          transition={transition}
        >
          <Circle className="size-2 fill-current stroke-none" />
        </motion.div>
      </AnimatePresence>
    </RadioPrimitive.Indicator>
  );
}

type PrimitiveRadioProps = React.ComponentProps<typeof RadioPrimitive.Root>;
type RadioGroupItemProps = PrimitiveRadioProps &
  Omit<HTMLMotionProps<'button'>, keyof PrimitiveRadioProps> &
  SharedProps & { transition?: Transition; variant?: 'card' | 'default' };

function RadioGroupItem({
  children,
  className,
  transition = DEFAULT_TRANSITION,
  testId,
  variant = 'default',
  nativeButton,
  render,
  ...props
}: RadioGroupItemProps) {
  const separated = splitMotionProps(props);
  const renderRoot: NonNullable<PrimitiveRadioProps['render']> = (rootProps, state) => {
    const Root: React.ElementType = nativeButton === false ? 'span' : 'button';
    return <Root {...rootProps} data-state={state.checked ? 'checked' : 'unchecked'} />;
  };
  return (
    <RadioPrimitive.Root
      {...separated.native}
      className={(state) =>
        cn(
          variant === 'card'
            ? 'flex h-auto min-h-12 w-full items-center justify-between gap-4 rounded-lg border border-border/70 bg-background px-4 py-3 text-left text-foreground ring-offset-background transition hover:border-foreground/30 hover:shadow-xs focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 data-[checked]:border-foreground data-[checked]:bg-muted/30 data-[checked]:shadow-xs'
            : 'relative flex aspect-square size-4 cursor-pointer items-center justify-center rounded-full border !border-input outline-none after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-[checked]:border-primary data-[checked]:bg-primary data-[checked]:text-primary-foreground motion-safe:hover:scale-105 motion-safe:active:scale-95 dark:bg-input/30 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40',
          typeof className === 'function' ? className(state) : className
        )
      }
      data-slot="radio-group-item"
      data-testid={testId}
      nativeButton={nativeButton ?? render === undefined}
      render={render ?? renderRoot}
    >
      <motion.span className="contents" {...separated.motion}>
        {children}
        {variant === 'card' ? (
          <span
            aria-hidden="true"
            className="flex aspect-square size-5 shrink-0 items-center justify-center rounded-full border !border-input text-selected"
          >
            <RadioGroupIndicator data-slot="radio-group-item-indicator" transition={transition} />
          </span>
        ) : (
          <RadioGroupIndicator data-slot="radio-group-item-indicator" transition={transition} />
        )}
      </motion.span>
    </RadioPrimitive.Root>
  );
}

export {
  RadioGroup,
  RadioGroupIndicator,
  type RadioGroupIndicatorProps,
  RadioGroupItem,
  type RadioGroupItemProps,
  type RadioGroupProps,
};

